                        "title": "Parameters",
                        "type": "array",
                        "minItems": 0,
                        "items": {
                            "title": "Parameter",
                            "type": "object",
                            "properties": {
                                "name": {
                                    "title": "Name",
                                    "type": "string"
                                },
                                "value": {
                                    "title": "Value"
                                }
                            }
                        }
                    }
