                    "description": "The parent content item.",
                    "maxItems": 1
                },
                "policy_areas": {
                    "$ref": "#/definitions/guid_list",
                    "description": "A largely deprecated tag currently only used to power email alerts."
                },
                "primary_publishing_organisation": {
                    "$ref": "#/definitions/guid_list",
                    "description": "The organisation that published the page. Corresponds to the first of the 'Lead organisations' in Whitehall, and is empty for all other publishing applications.",
                    "maxItems": 1
                },
                "suggested_ordered_related_items": {
                    "$ref": "#/definitions/guid_list",
                    "description": "New A/B test suggestions for related items. Used for displaying related content on most pages, except for step-by-step and fatality notices. Links and their ordering are determined by the machine learning algorithms included in this A/B test."
                },
                "taxons": {
                    "$ref": "#/definitions/guid_list",
                    "description": "Prototype-stage taxonomy label for this content item"
                },
                "topics": {
                    "$ref": "#/definitions/guid_list",
                    "description": "Powers the /topic section of the site. These are known as specialist sectors in some legacy apps."
                }
            },
            "type": "object"
        },
        "locale": {
            "$ref": "#/definitions/locale"
        },
        "navigation_document_supertype": {
            "description": "Document type grouping powering the new taxonomy-based navigation pages",
            "type": "string"
        },
        "need_ids": {
            "items": {
                "type": "string"
            },
            "type": "array"
        },
        "payload_version": {
            "$ref": "#/definitions/payload_version"
        },
        "phase": {
            "description": "The service design phase of this content item - https://www.gov.uk/service-manual/phases",
            "enum": [
                "alpha",
                "beta",
                "live"
            ],
            "type": "string"
        },
        "public_updated_at": {
            "$ref": "#/definitions/public_updated_at"
        },
        "publishing_app": {
            "$ref": "#/definitions/publishing_app_name"
        },
        "publishing_request_id": {
            "$ref": "#/definitions/publishing_request_id"
        },
        "redirects": {
            "additionalItems": false,
            "items": {},
            "type": "array"
        },
        "rendering_app": {
            "$ref": "#/definitions/rendering_app"
        },
        "routes": {
            "$ref": "#/definitions/routes"
        },
        "schema_name": {
            "enum": [
                "coming_soon"
            ],
            "type": "string"
        },
        "search_user_need_document_supertype": {
            "description": "Document supertype grouping core and government documents",
            "type": "string"
        },
        "title": {
            "$ref": "#/definitions/title"
        },
        "update_type": {
            "$ref": "#/definitions/update_type"
        },
        "user_journey_document_supertype": {
            "description": "Document type grouping powering analytics of user journeys",
            "type": "string"
        },
        "user_need_document_supertype": {
            "description": "DEPRECATED. Use `content_purpose_document_supertype`.",
            "type": "string"
        },
        "withdrawn_notice": {
            "$ref": "#/definitions/withdrawn_notice"
        }
    },
    "required": [
        "analytics_identifier",
        "base_path",
        "content_id",
        "description",
        "details",
        "document_type",
        "email_document_supertype",
        "expanded_links",
        "first_published_at",
        "government_document_supertype",
        "govuk_request_id",
        "links",
        "locale",
        "navigation_document_supertype",
        "payload_version",
        "phase",
        "public_updated_at",
        "publishing_app",
        "redirects",
        "rendering_app",
        "routes",
        "schema_name",
        "title",
        "update_type",
        "user_journey_document_supertype"
    ],
    "type": "object"
}

{
    "id": "https://tredly.com/docs/tredlyfile-json-schema#",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "description": "schema for an JSON Tredlyfile",
    "type": "object",
    "definitions": {
        "validPort": {
            "type": "integer",
            "minimum": 1,
            "maximum": 65535
        },
        "validAnyPort": {
            "type": "string",
            "enum": [
                "any"
            ]
        },
        "positiveInteger": {
            "type": "integer",
            "minimum": 0
        },
        "binaryStringType": {
            "type": "string",
            "enum": [
                "0",
                "1"
            ]
        },
        "stringPath": {
            "type": "string",
            "pattern": "^/"
        },
        "typeSizeMegabyte": {
            "type": "string",
            "pattern": "^[0-9]+(m|M)(b|B)?$"
        },
        "typeSizeGigabyte": {
            "type": "string",
            "pattern": "^[0-9]+(g|G)(b|B)?$"
        },
        "validIpv4": {
            "pattern": "^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$"
        },
        "validIpv4WithCidr": {
            "type": "string",
            "pattern": "^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])(/([0-9]|[1-2][0-9]|3[0-2]))?$"
        },
        "resourceUnlimited": {
            "type": "string",
            "enum": [
                "unlimited"
            ]
        },
        "inOutPorts": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "in": {
                    "type": "array",
                    "_uniqueItems": true,
                    "items": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/validPort"
                            },
                            {
                                "$ref": "#/definitions/validAnyPort"
                            }
                        ]
                    },
                    "default": {}
                },
                "out": {
                    "type": "array",
                    "_uniqueItems": true,
                    "items": {
                        "oneOf": [
                            {
                                "$ref": "#/definitions/validPort"
                            },
                            {
                                "$ref": "#/definitions/validAnyPort"
                            }
                        ]
                    },
                    "default": {}
                }
            }
        },
        "operationExec": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "exec"
                    ]
                },
                "value": {
                    "type": "string"
                }
            },
            "required": [
                "value"
            ],
            "additionalProperties": false
        },
        "operationFolderFileMapping": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "fileFolderMapping"
                    ]
                },
                "source": {
                    "type": "string"
                },
                "target": {
                    "type": "string"
                }
            },
            "required": [
                "source",
                "target"
            ],
            "additionalProperties": false
        },
        "operationInstallPackage": {
            "type": "object",
            "properties": {
                "type": {
                    "type": "string",
                    "enum": [
                        "installPackage"
                    ]
                },
                "value": {
                    "type": "string"
                }
            },
            "required": [
                "value"
            ],
            "additionalProperties": false
        },
        "arrayOfOperations": {
            "type": "array",
            "items": {
                "oneOf": [
                    {
                        "$ref": "#/definitions/operationExec"
                    },
                    {
                        "$ref": "#/definitions/operationFolderFileMapping"
                    },
                    {
                        "$ref": "#/definitions/operationInstallPackage"
                    }
                ]
            }
        },
        "arrayOfExecOperationsOnly": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/operationExec"
            }
        },
        "uriProtocolHttps": {
            "type": "string",
            "pattern": "^https:\\/\\/"
        },
        "uriProtocolHttp": {
            "type": "string",
            "pattern": "^http:\\/\\/"
        },
        "httpsRedirect": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "url": {
                    "$ref": "#/definitions/uriProtocolHttps"
                },
                "cert": {
                    "description": "SSL certificate to apply to a http redirect 'from' URL.",
                    "type": "string"
                }
            },
            "required": [
                "url",
                "cert"
            ]
        },
        "httpRedirect": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
                "url": {
                    "$ref": "#/definitions/uriProtocolHttp"
                },
                "cert": {
                    "type": "null",
                    "enum": [
                        null
                    ]
                }
            },
            "required": [
                "url",
                "cert"
            ]
        }
    },
    "required": [
        "container"
    ],
    "properties": {
        "container": {
            "type": "object",
            "properties": {
                "name": {
                    "description": "Unique per partition. Hostname of this container will this value",
                    "type": "string",
                    "pattern": "^[-_a-zA-Z0-9]+$"
                },
                "restrictTo": {
                    "description": "The version of Tredly this file is compatible with.",
                    "oneOf": [
                        {
                            "type": "string",
                            "pattern": "^(\\*|[0-9](?:\\.(\\*|[0-9]{1,}(?:\\.(\\*|[0-9]{1,}))?)?)?)$"
                        },
                        {
                            "type": "null"
                        },
                        {
                            "type": "string",
                            "maxLength": 0
                        }
                    ]
                },
                "group": {
                    "description": "Add this container to a particular group.",
                    "oneOf": [
                        {
                            "type": "string",
                            "pattern": "^[-_a-zA-Z0-9]+$"
                        },
                        {
                            "type": "null"
                        },
                        {
                            "type": "string",
                            "maxLength": 0
                        }
                    ],
                    "optional": true
                },
                "startOrder": {
                    "description": "Order in which this container is started within your container group.",
                    "type": "integer",
                    "minimum": 1,
                    "maximum": 99,
                    "default": 1
                },
                "replicate": {
                    "description": "When set to yes, this allows a container to be replicated within its container group. This is required if 'group' has been set.",
                    "type": "boolean",
                    "default": false
                },
                "buildOptions": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "publish": {
                            "description": "When set to true, on push to a Tredly host this container will be automatically validated and built.",
                            "type": "boolean",
                            "default": true
                        }
                    },
                    "required": [
                        "publish"
                    ]
                },
                "technicalOptions": {
                    "description": "These options will be set when the container is created.",
                    "type": "object",
                    "optional": true,
                    "additionalProperties": false,
                    "properties": {
                        "securelevel": {
                            "type": "integer",
                            "minimum": -1,
                            "maximum": 3
                        },
                        "devfs_ruleset": {
                            "$ref": "#/definitions/positiveInteger"
                        },
                        "enforce_statfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "children.max": {
                            "$ref": "#/definitions/positiveInteger"
                        },
                        "allow.set_hostname": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.sysvipc": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.raw_sockets": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.chflags": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.devfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.nullfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.procfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.tmpfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.mount.zfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.quotas": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "allow.socket_af": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.prestart": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.poststart": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.prestop": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.stop": {
                            "$ref": "#/definitions/stringPath"
                        },
                        "exec.clean": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.timeout": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "exec.fib": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "stop.timeout": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "mount.devfs": {
                            "$ref": "#/definitions/binaryStringType"
                        },
                        "mount.fdescfs": {
                            "$ref": "#/definitions/binaryStringType"
                        }
                    }
                },
                "persistentStorage": {
                    "type": "object",
                    "optional": true,
                    "description": "Create a persistent block of storage for this container",
                    "additionalProperties": false,
                    "properties": {
                        "identifier": {
                            "description": "A unique name to identify this block of persistent storage.",
                            "type": "string",
                            "pattern": "^[-_a-zA-Z0-9]+$"
                        },
                        "mountPoint": {
                            "description": "The path within the container that the persistent storage will be mounted.",
                            "$ref": "#/definitions/stringPath"
                        }
                    },
                    "required": [
                        "identifier",
                        "mountPoint"
                    ]
                },
                "resourceLimits": {
                    "description": "Limit resources used by this container.",
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "maxCpu": {
                            "description": "The total number of cores or percent this container can utilise.",
                            "oneOf": [
                                {
                                    "type": "string",
                                    "pattern": "^[0-9]+%$"
                                },
                                {
                                    "type": "integer",
                                    "minimum": 1
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        },
                        "maxHdd": {
                            "description": "The total amount of disk space, in Gigabytes (G) or Megabytes (M), this container.",
                            "oneOf": [
                                {
                                    "$ref": "#/definitions/typeSizeMegabyte"
                                },
                                {
                                    "$ref": "#/definitions/typeSizeGigabyte"
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        },
                        "maxRam": {
                            "description": "The total amount of RAM, in Gigabytes (G) or Megabytes (M), this container can utilise.",
                            "oneOf": [
                                {
                                    "$ref": "#/definitions/typeSizeMegabyte"
                                },
                                {
                                    "$ref": "#/definitions/typeSizeGigabyte"
                                },
                                {
                                    "$ref": "#/definitions/resourceUnlimited"
                                }
                            ],
                            "optional": true,
                            "default": "unlimited"
                        }
                    }
                },
                "proxy": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "layer4Proxy": {
                            "description": "Layer4 proxy allows the container to use the Hosts external IP and forward traffic to your container on specific ports.",
                            "type": "boolean",
                            "default": false
                        },
                        "layer7Proxy": {
                            "description": "Group of properties for URL(s) the container services and responds to.",
                            "optional": true,
                            "type": "array",
                            "items": {
                                "type": "object",
                                "additionalProperties": false,
                                "properties": {
                                    "url": {
                                        "type": "string"
                                    },
                                    "cert": {
                                        "type": [
                                            "string",
                                            "null"
                                        ]
                                    },
                                    "enableWebsocket": {
                                        "optional": true,
                                        "type": "boolean",
                                        "default": false
                                    },
                                    "errorResponse": {
                                        "type": "boolean",
                                        "default": true
                                    },
                                    "maxFileSize": {
                                        "type": "string",
                                        "optional": true,
                                        "pattern": "^[0-9]+(m|g)$",
                                        "default": "1m"
                                    },
                                    "redirects": {
                                        "type": "array",
                                        "optional": true,
                                        "items": {
                                            "type": "object",
                                            "anyOf": [
                                                {
                                                    "$ref": "#/definitions/httpRedirect"
                                                },
                                                {
                                                    "$ref": "#/definitions/httpsRedirect"
                                                }
                                            ]
                                        }
                                    }
                                },
                                "required": [
                                    "url",
                                    "cert"
                                ]
                            }
                        }
                    },
                    "required": [
                        "layer4Proxy"
                    ]
                },
                "firewall": {
                    "type": "object",
                    "optional": true,
                    "properties": {
                        "ipv4Whitelist": {
                            "type": "array",
                            "optional": true,
                            "_uniqueItems": true,
                            "default": {},
                            "items": {
                                "$ref": "#/definitions/validIpv4WithCidr"
                            }
                        },
                        "allowPorts": {
                            "type": "object",
                            "optional": true,
                            "additionalProperties": false,
                            "_uniqueItems": true,
                            "properties": {
                                "udp": {
                                    "$ref": "#/definitions/inOutPorts"
                                },
                                "tcp": {
                                    "$ref": "#/definitions/inOutPorts"
                                }
                            }
                        }
                    }
                },
                "customDNS": {
                    "type": "array",
                    "_uniqueItems": true,
                    "optional": true,
                    "default": {},
                    "items": {
                        "$ref": "#/definitions/validIpv4"
                    }
                },
                "operations": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                        "onStart": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        },
                        "onStop": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        },
                        "onCreate": {
                            "$ref": "#/definitions/arrayOfOperations"
                        },
                        "onDestroy": {
                            "$ref": "#/definitions/arrayOfExecOperationsOnly"
                        }
                    }
                }
            }
        }
    }
}

{
    "$id": "https://raw.githubusercontent.com/edertone/TurboBuilder/master/TurboBuilder-Node/src/main/resources/json-schema/turbodepot.schema.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "title": "turbodepot.json schema",
    "required": [
        "$schema",
        "depots",
        "sources"
    ],
    "additionalProperties": false,
    "properties": {
        "$schema": {
            "type": "string",
            "description": "Url to the json schema definition to validate this file",
            "enum": [
                "https://raw.githubusercontent.com/edertone/TurboBuilder/master/TurboBuilder-Node/src/main/resources/json-schema/turbodepot.schema.json"
            ]
        },
        "depots": {
            "type": "array",
            "description": "",
            "items": {
                "type": "object",
                "description": "",
                "required": [
                    "name",
                    "storageFolderPath",
                    "tmpFiles",
                    "localizedFiles",
                    "logs",
                    "objects",
                    "googleDrive",
                    "users"
                ],
                "additionalProperties": false,
                "properties": {
                    "name": {
                        "type": "string",
                        "description": ""
                    },
                    "storageFolderPath": {
                        "type": "string",
                        "description": "The full file system path to the root of the storage folder (if used)"
                    },
                    "tmpFiles": {
                        "type": "object",
                        "description": "Defines the setup for the storage of temporary files into this depot instance",
                        "required": [
                            "source"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "source": {
                                "type": "string",
                                "description": "The name for a source that will be used to store and read the temporary files"
                            }
                        }
                    },
                    "localizedFiles": {
                        "type": "object",
                        "description": "Defines the setup for the storage of localized files into this depot instance",
                        "required": [
                            "source"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "source": {
                                "type": "string",
                                "description": "The name for a source that will be used to store and read the localized files"
                            },
                            "locales": {
                                "type": "array",
                                "description": "The list of locales that will be used to perform translations on the item names. Sorted by preference, like: 'en_US', 'es_ES' (see TurboCommons LocalizedFilesManager constructor docs for more info)"
                            },
                            "locations": {
                                "type": "array",
                                "description": "A list (sorted by preference) where each item defines a translations location (see TurboCommons LocalizedFilesManager constructor docs for more info)"
                            },
                            "failIfKeyNotFound": {
                                "type": "boolean",
                                "description": "True to throw an exception if any localization key is not found (see TurboCommons LocalizedFilesManager constructor docs for more info)"
                            }
                        }
                    },
                    "logs": {
                        "type": "object",
                        "description": "Defines the setup for the storage of logs into this depot instance",
                        "required": [
                            "source"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "source": {
                                "type": "string",
                                "description": "The name for a source that will be used to store and read the logs"
                            }
                        }
                    },
                    "objects": {
                        "type": "object",
                        "description": "",
                        "required": [
                            "source"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "source": {
                                "type": "string",
                                "description": ""
                            }
                        }
                    },
                    "googleDrive": {
                        "type": "object",
                        "description": "Defines the setup for the google drive client",
                        "required": [
                            "accountCredentialsPath",
                            "apiClientRoot",
                            "cacheRootPath",
                            "cacheZone",
                            "listsTimeToLive",
                            "filesTimeToLive"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "accountCredentialsPath": {
                                "type": "string",
                                "description": "A full file system path to the file that contains the service account credentials that will be used to authenticate with the google drive API"
                            },
                            "apiClientRoot": {
                                "type": "string",
                                "description": "A full file system path to the root of the google-api-php-client library. See GoogleDriveManager class for more info"
                            },
                            "cacheRootPath": {
                                "type": "string",
                                "description": "A full file system path to the root of the folder where the cached google drive files will be stored. Set it to empty string to disable local cache. See GoogleDriveManager class for more info"
                            },
                            "cacheZone": {
                                "type": "string",
                                "description": "The name for the cache zone where the google drive cached files will be stored. See GoogleDriveManager class for more info"
                            },
                            "listsTimeToLive": {
                                "type": "integer",
                                "description": "Defines the number of seconds after which the operations related to listing files and folder cache data will be deleted. Set it to 0 to for an infinite time. (1 hour = 3600 seconds, 1 day = 86400 seconds, 1 month = 2592000, 1 year = 31536000)"
                            },
                            "filesTimeToLive": {
                                "type": "integer",
                                "description": "Defines the number of seconds after which the operations related to getting files content cache data will be deleted. Set it to 0 to for an infinite time. (1 hour = 3600 seconds, 1 day = 86400 seconds, 1 month = 2592000, 1 year = 31536000)"
                            }
                        }
                    },
                    "users": {
                        "type": "object",
                        "description": "Defines the setup for the storage of users into this depot instance",
                        "required": [
                            "source",
                            "prefix",
                            "tokenLifeTime",
                            "isTokenLifeTimeRecycled"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "source": {
                                "type": "string",
                                "description": "The name for a source that will be used to store and read the users"
                            },
                            "prefix": {
                                "type": "string",
                                "description": "The prefix to use with database table names for all the user related database tables. This will help with avoiding table name collisions on a database"
                            },
                            "tokenLifeTime": {
                                "type": "integer",
                                "description": "Defines the number of seconds that user tokens will be active since they are created. After the number of seconds has passed, tokens will expire and a login will be necessary to obtain a new token"
                            },
                            "isTokenLifeTimeRecycled": {
                                "type": "boolean",
                                "description": "If set to true, every time a token is validated the lifetime will be restarted to the configured token lifetime. So the token lifetime will start counting again after the last token validation has been performed. So with a 10 minutes token lifetime if we perform 2 token validations in 5 minutes, the time will still be 10 minutes after the last validation's been performed."
                            }
                        }
                    }
                }
            }
        },
        "sources": {
            "type": "object",
            "description": "Defines the destinations where the data will be saved and read",
            "required": [],
            "additionalProperties": false,
            "properties": {
                "fileSystem": {
                    "type": "array",
                    "description": "Defines a source that stores all data using OS files and folders",
                    "items": {
                        "type": "object",
                        "description": "",
                        "required": [
                            "name",
                            "path"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "A name we want to use as an alias for this file system source"
                            },
                            "path": {
                                "type": "string",
                                "description": "An absolute path that points to the root of this file system source. This is where the data will be stored when we use this source alias on our depots"
                            }
                        }
                    }
                },
                "mariadb": {
                    "type": "array",
                    "description": "Defines a source that stores all data using a MariaDb or Mysql (legacy) database storage engine",
                    "items": {
                        "type": "object",
                        "description": "",
                        "required": [
                            "name",
                            "host",
                            "database",
                            "user",
                            "password"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": "A name we want to use as an alias for this database source"
                            },
                            "host": {
                                "type": "string",
                                "description": "The host where database is found. Usually localhost if the db is on the same machine, but may be any ip or hostname where db may be found"
                            },
                            "database": {
                                "type": "string",
                                "description": "The name for the database to which this source will be connected"
                            },
                            "user": {
                                "type": "string",
                                "description": "The user name that will be used to connect to this source's database"
                            },
                            "password": {
                                "type": "string",
                                "description": "The password to use with the user when connecting to database"
                            }
                        }
                    }
                },
                "sqLite": {
                    "type": "array",
                    "description": "Defines a source that stores all data using an SQLite database storage engine",
                    "items": {
                        "type": "object",
                        "description": "",
                        "required": [
                            "name",
                            "path",
                            "prefix"
                        ],
                        "additionalProperties": false,
                        "properties": {
                            "name": {
                                "type": "string",
                                "description": ""
                            },
                            "path": {
                                "type": "string",
                                "description": ""
                            },
                            "prefix": {
                                "type": "string",
                                "description": ""
                            }
                        }
                    }
                }
            }
        }
    }
}

