{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "additionalProperties": false,
  "definitions": {
    "Table": {
      "type": "object",
      "title": "Table",
      "additionalProperties": false,
      "required": ["Tablename", "Identifier", "Module", "PermissionKey"],
      "properties": {
        "Tablename": {
          "type": "string",
          "description": "Table name",
          "minLength": 1
        },
        "Identifier": {
          "type": "string",
          "description": "Row identifier without Row suffix",
          "minLength": 1
        },
        "Module": {
          "type": "string",
          "description": "Module name",
          "minLength": 1
        },
        "PermissionKey": {
          "type": "string",
          "description": "Permission key",
          "minLength": 1
        }
      }
    },
    "Connection": {
      "type": "object",
      "title": "Connection",
      "additionalProperties": false,
      "required": ["Key"],
      "properties": {
        "Key": {
          "type": "string",
          "description": "Key of connection",
          "minLength": 1
        },
        "ConnectionString": {
          "type": "string",
          "description": "Connection string",
          "minLength": 1
        },
        "ProviderName": {
          "type": "string",
          "description": "Provider name",
          "minLength": 1
        },
        "Dialect": {
          "type": "string",
          "title": "Dialect",
          "minLength": 1,
          "description": "Dialect",
          "anyOf": [
            {
              "enum": [
                "SqlServer",
                "SqlServer2012",
                "SqlServer2008",
                "SqlServer2005",
                "SqlServer2000",
                "Sqlite",
                "Postgres",
                "Oracle",
                "Oracle12c",
                "MySql",
                "Firebird"
              ]
            },
            {
              "type": "string"
            }
          ]
