{
  "$comment": "https://probot.github.io/apps/stale/",
  "$ref": "#/definitions/configuration",
  "$schema": "http://json-schema.org/draft-04/schema#",
  "definitions": {
    "configuration": {
      "properties": {
        "daysUntilStale": {
