                  "type": "string",
                  "description": "Select a specific profile from your credential file to get AWS credentials."
                },
                "region": {
                  "title": "region",
                  "type": "string",
                  "description": "Set the AWS Region of the service. (e.g. us-east-1)"
                }
              }
            }
          },
