      "type": "string",
      "minLength": 1
    },
    "ignore": {
      "description": "Patterns for ignoring fixture and decorator files (eg. [\"**/dist/**\"]]).",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "watchDirs": {
      "description": "Directories where the Cosmos server watches for fixture files changes while running. [default: [\".\"]]",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "lazy": {
      "description": "Dynamically import fixture and decorator modules as they are loaded. When false all fixture and decorator modules are imported statically and bundled together. [default: false]",
      "type": "boolean"
    },
    "exposeImports": {
      "description": "Expose user imports and config required for the Cosmos renderer. Used with React Native and in custom integrations. When a path is specified it requires a file extension (eg. \"src/cosmos.imports.ts\"). [default: false]",
      "anyOf": [
        {
          "type": "string",
          "minLength": 1
        },
        {
          "type": "boolean"
        }
      ]
    },
    "hostname": {
      "description": "Dev server hostname. Set to null to accept connections with any hostname. [default: null]",
      "anyOf": [
        {
          "type": "string",
          "minLength": 1
        },
        {
          "type": "null"
        }
      ]
    },
    "port": {
      "description": "Dev server port. [default: 5000]",
      "type": "number"
    },
    "portRetries": {
      "description": "Max number of port retries. [default: 10]",
      "type": "number"
    },
    "https": {
      "description": "Server will be served over HTTPS.",
      "type": "boolean"
    },
    "httpsOptions": {
      "description": "Additional options for HTTPS server.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "certPath": {
          "description": "Path of a certificate file",
          "type": "string"
        },
        "keyPath": {
          "description": "Path of a certificate's key file",
          "type": "string"
        }
      }
    },
    "httpProxy": {
      "description": "Proxy some URLs to a different HTTP server (eg. an API backend dev server). Similar to devServer.proxy in webpack config.",
      "type": "object",
      "additionalProperties": true,
      "patternProperties": {
        ".*": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "object",
              "description": "Advanced HTTP proxy config.",
              "additionalProperties": true,
              "required": ["target"],
              "properties": {
                "target": {
                  "type": "string"
                },
                "secure": {
                  "type": "boolean"
                },
                "pathRewrite": {
                  "type": "object",
                  "patternProperties": {
                    ".*": {
                      "type": "string"
                    }
                  }
                },
                "logLevel": {
                  "type": "string",
                  "enum": ["error", "debug", "info", "warn", "silent"]
                }
              }
            }
          ]
        }
      }
    },
    "globalImports": {
      "description": "Modules to be imported before loading components. Stuff like reset.css, polyfills, etc.",
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true
    },
    "rendererUrl": {
      "description": "Required when renderer doesn't run on the same port (or host) as the Playground. Useful for integrations with build tools. [default: null]",
      "anyOf": [
        {
          "type": "string",
          "minLength": 1
        },
        {
          "type": "null"
        }
      ]
    },
    "dom": {
      "description": "DOM-related options",
      "type": "object",
      "properties": {
        "containerQuerySelector": {
          "description": "Document selector for existing element to use as component parent (eg. #root). A blank container element is created from scratch if no selector is provided. [default: null]",
          "type": ["string", "null"],
          "minLength": 1
        }
      }
    },
    "vite": {
      "description": "Vite-related options",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "configPath": {
          "description": "Path to Vite config. Set to false to disable reading it from the default path. [default: \"vite.config.js\"]",
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "enum": [false]
            }
          ]
        },
        "indexPath": {
          "description": "Path to index module (eg. \"src/my-index.tsx\"). [default: matches common index/main module paths]",
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ]
        },
        "port": {
          "description": "Vite renderer port. [default: 5050]",
          "type": "number"
        }
      }
    },
    "webpack": {
      "description": "Webpack-related options",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "configPath": {
          "description": "Path to an existing webpack config, which Cosmos will reuse to build your code. Set to null to disable this behavior. [default: \"webpack.config.js\"]",
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ]
        },
        "overridePath": {
          "description": "Path to a user module that customizes the webpack config used by Cosmos. Set to null to disable this behavior. [default: \"webpack.override.js\"]",
          "anyOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ]
        },
        "includeHashInOutputFilename": {
          "description": "Changes output filename from \"[name].js\" to \"[name].[contenthash].js\". [default: false]",
          "type": "boolean"
        },
        "hotReload": {
          "description": "Enable webpack's Hot Module Replacement. [default: true]",
          "type": "boolean"
        },
        "reloadOnFail": {
          "description": "When using webpack's Hot Module Replacement, enable automatic location reload after webpack fails to update modules. [default: false]",
          "type": "boolean"
        }
      }
    },
    "ui": {
      "description": "UI plugin options",
      "type": "object",
      "additionalProperties": true,
      "properties": {
        "responsivePreview": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "devices": {
              "description": "List of device viewports",
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": ["label", "width", "height"],
                "properties": {
                  "label": {
                    "type": "string",
                    "minLength": 1
                  },
                  "width": {
                    "type": "number",
                    "minimum": 1
                  },
                  "height": {
                    "type": "number",
                    "minimum": 1
                  }
                }
              }
            }
          }
        }
      }
    }
  },
  "title": "JSON schema for React Cosmos configs",
  "type": "object"
}

{
  "$id": "https://json.schemastore.org/ts-force-config.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "AuthConfig": {
      "properties": {
        "accessToken": {
          "type": "string"
        },
        "clientId": {
          "type": "string"
        },
        "clientSecret": {
          "type": "string"
        },
        "instanceUrl": {
          "type": "string"
        },
        "oAuthHost": {
          "type": "string"
        },
        "password": {
          "type": "string"
        },
        "username": {
          "description": "If using `sfdx-cli` auth, this is the only property needed to authenticate.\nOtherwise, supply additional oAuth parameters",
          "type": "string"
        },
        "version": {
          "type": "number"
        }
      },
      "type": "object"
    },
    "FieldMapping": {
      "properties": {
        "apiName": {
          "description": "The Target SObject API name",
          "type": "string"
        },
        "propName": {
          "description": "The generated class property name",
          "type": "string"
        }
      },
      "required": ["apiName", "propName"],
      "type": "object"
    },
    "SObjectConfig": {
      "description": "Object used to configure advanced settings on SObject generation",
      "properties": {
        "apiName": {
          "description": "The Target SObject API name",
          "type": "string"
        },
        "autoConvertNames": {
          "description": "Defaulted to true.  If set to false, names will NOT be auto-converted to standard javascript conventions",
          "type": "boolean"
        },
        "className": {
          "description": "The generated class name.  If not set, it will be automatically\nconverted to standard javascript Class convention",
          "type": "string"
        },
        "enforcePicklistValues": {
          "description": "*Overrides Global Setting*\nThe path to generate files to.\n   If the destination is a folder, it will generate one file per object.\n   If the destination is a `.ts` file, a single file will be generated.\n   If not set, class output will be logged to `stdout`",
          "enum": ["ALL", "RESTRICTED", false]
        },
        "fieldMappings": {
          "description": "List of field mappings to override the auto-conversion",
          "items": {
            "$ref": "#/definitions/FieldMapping"
          },
          "type": "array"
        },
        "generatePicklists": {
          "description": "*Overrides Global Setting*\nMake picklist fields strongly typed to generated enums. `generatePicklists` must also be `true`\n  `ALL`: for all picklist fields, regardless of salesforce enforcement\n  `RESTRICTED`: only on fields where the values are restricted on Salesforce",
          "type": "boolean"
        }
      },
      "required": ["apiName"],
      "type": "object"
    }
  },
  "properties": {
    "auth": {
      "$ref": "#/definitions/AuthConfig",
      "description": "Authentication Method.  Choose one of three:\n- You can either username/password oAuth configuration\n- sfdx configuration (`username` only)\n- `accessToken` & `instanceUrl`\nSee readme for examples."
    },
    "enforcePicklistValues": {
      "description": "Make picklist fields strongly typed to generated enums. `generatePicklists` must also be `true`\n  `ALL`: for all picklist fields, regardless of salesforce enforcement\n  `RESTRICTED`: only on fields where the values are restricted on Salesforce",
      "enum": ["ALL", "RESTRICTED", false]
    },
    "generatePicklists": {
      "description": "Flag to generate enums for picklist fields.  Defaulted to false",
      "type": "boolean"
    },
    "outPath": {
      "description": "The path to generate files to.\n   If the destination is a folder, it will generate one file per object.\n   If the destination is a `.ts` file, a single file will be generated.\n   If not set, class output will be logged to `stdout`",
      "type": "string"
    },
    "sObjects": {
      "description": "The SObjects to generate classes for.  Can either be a string or an `SObjectConfig` object",
      "items": {
        "anyOf": [
          {
            "$ref": "#/definitions/SObjectConfig"
          },
          {
            "type": "string"
          }
        ]
      },
      "type": "array"
    }
  },
  "type": "object"
}

