            "branches": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": ["*"],
              "description": "Push 빌드의 branch 조건",
              "minItems": 1
            },
            "tags": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": ["*"],
              "description": "Push 빌드의 tag 조건",
              "minItems": 1
            },
            "commit": {
              "type": "object",
              "properties": {
                "message-contain": {
                  "type": "string",
                  "description": "commit message에 주어진 문자열을 포함한 경우만 빌드"
                }
              }
            }
          },
          "additionalProperties": false
        },
        "pull-request": {
          "type": "object",
          "description": "PullRequest 이벤트에 의한 조건",
          "properties": {
            "branches": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": ["*"],
              "description": "PR빌드의 target 브랜치 조건",
              "minItems": 1
            },
            "types": {
              "type": "array",
