        "description" : "Which time (UTC) should retention-cleanup be performed"
      } ]
    },
    "email" : {
      "type" : [ "object", "null" ],
      "properties" : {
        "administratorAddress" : {
          "allOf" : [ {
            "$ref" : "#/definitions/EmailAddress"
          }, {
            "description" : "Email address notifications are sent to"
          } ]
        },
        "authentication" : {
          "type" : [ "object", "null" ],
          "properties" : {
            "password" : {
              "$ref" : "#/definitions/EncryptedSecret"
            },
            "type" : {
              "type" : "string",
              "enum" : [ "login", "cramMd5", "plain" ]
            },
            "username" : {
              "type" : "string"
            }
          },
          "required" : [ "password", "type", "username" ],
          "additionalProperties" : false,
          "minProperties" : 1,
          "description" : "SMTP authentication method"
        },
        "fromAddress" : {
          "allOf" : [ {
            "$ref" : "#/definitions/EmailAddress"
          }, {
            "description" : "Email address notifications are sent from"
          } ]
        },
        "smtpServer" : {
          "type" : "string",
          "pattern" : "^(?:(?:(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])|(?:(?:[a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9])\\.)*(?:[A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9])):(?:[1-9][0-9]{0,3}|[1-6][0-5][0-5][0-3][0-5])$",
          "description" : "Address and port of the smtp server"
        },
        "sslProtocol" : {
          "anyOf" : [ {
            "type" : "null"
          }, {
            "type" : "string",
            "enum" : [ null, "startTls", "implicitTls" ],
            "description" : "SMTP protocol flavour"
          } ]
        }
      },
      "required" : [ "administratorAddress", "fromAddress", "smtpServer" ],
      "additionalProperties" : false,
      "minProperties" : 1,
      "description" : "SMTP configuration for notifications"
    },
    "helpContact" : {
      "type" : "object",
      "properties" : {
        "email" : {
          "anyOf" : [ {
            "type" : "null"
          }, {
            "$ref" : "#/definitions/EmailAddress"
          } ],
          "description" : "The email address users should contact"
        },
        "name" : {
          "type" : [ "string", "null" ],
          "description" : "The name of the contact"
        }
      },
      "additionalProperties" : false,
      "minProperties" : 1,
      "description" : "Who users should contact if they have a problem"
    },
    "network" : {
      "type" : [ "object", "null" ],
      "properties" : {
        "additionalTrust" : {
          "type" : [ "string", "null" ],
          "pattern" : "(?:^|\\r?\\n)-----BEGIN CERTIFICATE-----(?:\\r?\\n)(?:(?:\\s*[A-Za-z0-9+/]){4})*(?:(?:\\s*[A-Za-z0-9+/]){2}(?:\\s*=){2}|(?:\\s*[A-Za-z0-9+/]){3}(?:\\s*=))?\\s*(?:\\r?\\n)-----END CERTIFICATE-----(?:$|\\r?\\n)",
          "format" : "gradle-enterprise:x509-certs-pem",
          "description" : "Required if Gradle Enterprise must communicate with servers using certificates not trusted by default"
        },
        "proxy" : {
          "type" : [ "object", "null" ],
          "properties" : {
            "auth" : {
              "type" : [ "object", "null" ],
              "properties" : {
                "password" : {
                  "allOf" : [ {
                    "$ref" : "#/definitions/EncryptedSecret"
                  }, {
                    "description" : "Proxy password"
                  } ]
                },
                "username" : {
                  "type" : "string",
                  "description" : "Proxy username"
                }
              },
              "required" : [ "password", "username" ],
              "additionalProperties" : false,
              "minProperties" : 1,
              "description" : "Proxy authentication credentials"
            },
            "excludedHosts" : {
              "description" : "A list of hosts that should not be proxied",
              "type" : "array",
              "items" : {
                "type" : "string",
                "pattern" : "^(?:(?:(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])|(?:(?:^[\\*]|[a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9])\\.)*(?:[A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9]))$",
                "format" : "gradle-enterprise:excludedHosts"
              }
            },
            "host" : {
              "type" : "string",
              "pattern" : "^(?:(?:(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}(?:[0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])|(?:(?:[a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]*[a-zA-Z0-9])\\.)*(?:[A-Za-z0-9]|[A-Za-z0-9][A-Za-z0-9\\-]*[A-Za-z0-9]))$",
              "format" : "gradle-enterprise:host",
              "description" : "Proxy host"
            },
            "port" : {
              "type" : "integer",
              "description" : "Proxy port",
              "maximum" : 65535,
              "minimum" : 1
            },
            "protocol" : {
              "type" : "string",
              "enum" : [ "http", "https" ],
              "description" : "Proxy protocol"
            }
          },
          "required" : [ "host" ],
          "additionalProperties" : false,
          "minProperties" : 1,
          "description" : "Http proxy config"
        }
      },
      "additionalProperties" : false,
      "minProperties" : 1,
      "description" : "Network configuration"
    },
    "objectStorage" : {
      "type" : "object",
      "properties" : {
        "provider" : {
          "anyOf" : [ {
            "type" : "null"
          }, {
            "type" : "object",
            "properties" : {
              "type" : {
                "enum" : [ "s3" ]
              }
            },
            "required" : [ "type" ],
            "allOf" : [ {
              "if" : {
                "properties" : {
                  "type" : {
                    "const" : "s3"
                  }
                }
              },
              "then" : {
                "type" : "object",
                "required" : [ "bucket", "credentials", "region" ],
                "additionalProperties" : false,
                "minProperties" : 1,
                "properties" : {
                  "type" : {
                    "const" : "s3"
                  },
                  "bucket" : {
                    "type" : "string",
                    "description" : "The name of the bucket to store the scan payloads"
                  },
                  "credentials" : {
                    "allOf" : [ {
                      "if" : {
                        "properties" : {
                          "source" : {
                            "const" : "configuration"
                          }
                        }
                      },
                      "then" : {
                        "type" : "object",
                        "required" : [ "accessKey", "secretKey" ],
                        "additionalProperties" : false,
                        "minProperties" : 1,
                        "properties" : {
                          "source" : {
                            "const" : "configuration"
                          },
                          "accessKey" : {
                            "type" : "string"
                          },
                          "secretKey" : {
                            "$ref" : "#/definitions/EncryptedSecret"
                          }
                        }
                      }
                    }, {
                      "if" : {
                        "properties" : {
                          "source" : {
                            "const" : "environment"
                          }
                        }
                      },
                      "then" : {
                        "type" : "object",
                        "additionalProperties" : false,
                        "minProperties" : 1,
                        "properties" : {
                          "source" : {
                            "const" : "environment"
                          }
                        }
                      }
                    } ],
                    "type" : "object",
                    "properties" : {
                      "source" : {
                        "enum" : [ "configuration", "environment" ]
                      }
                    },
                    "required" : [ "source" ],
                    "minProperties" : 1,
                    "description" : "The aws credentials"
                  },
                  "region" : {
                    "type" : "string",
                    "description" : "The region of the bucket"
                  }
                }
              }
            } ],
            "minProperties" : 1
          } ]
        }
      },
      "additionalProperties" : false,
      "minProperties" : 1,
      "description" : "Object Storage configuration"
    },
    "systemPassword" : {
      "allOf" : [ {
        "$ref" : "#/definitions/HashedSecret"
      }, {
        "description" : "The password for the system user"
      } ]
    }
  }
}

{
  "$id": "https://json.schemastore.org/dart-test",
  "$ref": "#/definitions/runnerConfiguration",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "definitions": {
    "timeout": {
      "$comment": "Based on https://github.com/dart-lang/test/blob/3b8d3b90efd24f55f7316cd414716d1cb031761c/pkgs/test_api/lib/src/frontend/timeout.dart#L55-L68",
      "oneOf": [
        {
          "enum": ["none"],
          "title": "No timeout",
          "description": "Indicates that tests should never time out."
        },
        {
          "type": "string",
          "title": "Exact timeout",
          "description": "Exact timeout duration for a test.",
          "pattern": "^(?:[^a-df-zA-DF-Z\\s]+(?:[umUM][sS]|[dhmsDHMS])\\s?)+$",
          "examples": ["1m", "30s", "1m 30s"]
        },
        {
          "type": "string",
          "title": "Multiplicative timeout",
          "description": "Timeout is applied as a multiple of the default value (30 seconds)",
          "pattern": "^[^a-df-zA-DF-Z\\s]+[xX]$",
          "examples": ["12x", "1.5X"]
        }
      ]
    },
    "skip": {
      "oneOf": [
        {
          "type": "boolean",
          "title": "Skip the test if true"
        },
        {
          "type": "string",
          "title": "Reason for skipping the test"
        }
      ]
    },
    "executable": {
      "type": "string",
      "description": "The executable to run. Can be a plain basename, an absolute path or a relative path on Windows."
    },
    "browserAndNodeSettings": {
      "type": "object",
      "title": "Settings for browsers and Node.js",
      "additionalProperties": false,
      "properties": {
        "arguments": {
          "type": "string",
          "title": "Extra arguments to the executable",
          "description": "The arguments are parsed in the same way as the POSIX shell"
        },
        "executable": {
          "oneOf": [
            {
              "$ref": "#/definitions/executable"
            },
            {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "linux": {
                  "$ref": "#/definitions/executable"
                },
                "mac_os": {
                  "$ref": "#/definitions/executable"
                },
                "windows": {
                  "$ref": "#/definitions/executable"
                }
              }
            }
          ]
        },
        "headless": {
          "type": "boolean",
          "title": "Run the browser in headless mode"
        }
      }
    },
    "foldStackFrameOptions": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "except": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "only": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          }
        }
      ]
    },
    "testConfiguration": {
      "type": "object",
      "$comment": "Based on https://github.com/dart-lang/test/blob/master/pkgs/test/doc/configuration.md#test-configuration",
      "properties": {
        "timeout": {
          "$ref": "#/definitions/timeout"
        },
        "verbose_trace": {
          "type": "boolean",
          "title": "Remove internal stack frames",
          "description": "This field controls whether or not traces caused by errors are trimmed to remove internal stack frames. This includes frames from the Dart core libraries, the stack_trace package, and the test package itself.",
          "default": false
        },
        "chain_stack_traces": {
          "type": "boolean",
          "title": "Whether stack traces are chained",
          "description": "Disabling stack trace chaining will improve performance for heavily async code at the cost of debuggability."
        },
        "js_trace": {
          "type": "boolean",
          "title": "Convert JS traces to Dart traces",
          "description": "Whether or not stack traces caused by errors while running Dart compiled to JS are converted back to Dart style.",
          "default": false
        },
        "skip": {
          "$ref": "#/definitions/skip"
        },
        "retry": {
          "type": "number",
          "description": "This field controls how many times a test is retried upon failure."
        },
        "test_on": {
          "type": "string",
          "examples": ["browser && !ie"]
        },
        "tags": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/_testConfigurationInner"
          }
        },
        "add_tags": {
          "type": "array",
          "description": "Adds additional tags. This is usually used in a tag definition to enable tag inheritance.",
          "items": {
            "type": "string"
          }
        },
        "on_platform": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/definitions/_testConfigurationInner"
          }
        }
      }
    },
    "_testConfigurationInner": {
      "$comment": "presets and on_os can have different properties when used in a test vs runner configuration. We make runnerConfiguration extend from testConfiguration, so this configuration is used when we're definitely in a non-runner configuration context.",
      "allOf": [
        {
          "$ref": "#/definitions/testConfiguration"
        },
        {
          "properties": {
            "presets": {
              "type": "object",
              "description": "A preset used in a test configuration can contain test configuration.",
              "additionalProperties": {
                "$ref": "#/definitions/testConfiguration"
              }
            },
            "on_os": {
              "type": "object",
              "description": "Applies test options when a specific operating system is used",
              "additionalProperties": {
                "$ref": "#/definitions/testConfiguration"
              }
            }
          }
        }
      ]
    },
    "runnerConfiguration": {
      "allOf": [
        {
          "$comment": "Runner configurations are a superset of test configurations",
          "$ref": "#/definitions/testConfiguration"
        },
        {
          "properties": {
            "include": {
              "type": "string",
              "format": "uri"
            },
            "paths": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": ["test"]
            },
            "filename": {
              "type": "string",
              "description": "Filename pattern that the test runner uses to find test files in directories."
            },
            "names": {
              "type": "array",
              "description": "Only run tests whose names match the given regular expressions A test's name must match all regular expressions in names in order to be run.",
              "items": {
                "type": "string"
              }
            },
            "plain_names": {
              "type": "array",
              "description": "This field causes the runner to only run tests whose names contain the given strings. A test's name must contain all strings in order to be run.",
              "items": {
                "type": "string"
              }
            },
            "include_tags": {
              "type": "string",
              "description": "This field causes the runner to only run tests whose tags match the given boolean selector."
            },
            "exclude_tags": {
              "type": "string",
              "description": "This field causes the runner to only run tests whose tags match the given boolean selector. This takes precedence over include_tags"
            },
            "platforms": {
              "description": "The platforms on which tests should be run.",
              "type": "array",
              "items": {
                "type": "string"
              },
              "default": ["vm"]
            },
            "concurrency": {
              "type": "integer",
              "description": "The default number of test suites to run in parallel. This defaults to approximately half the number of processors on the current machine. Setting it to 1 will disable concurrency"
            },
            "pause_after_load": {
              "type": "boolean",
              "description": "Indicates that the test runner should pause for debugging after each test suite is loaded but before its tests are executed. This disables concurrency and timeouts."
            },
            "run_skipped": {
              "type": "boolean",
              "description": "Run tests even if they're marked as skipped."
            },
            "reporter": {
              "type": "string",
              "description": "This field indicates the default reporter to use.",
              "examples": ["compact", "expanded", "json"]
            },
            "file_reporters": {
              "type": "object",
              "description": "Specifies additional reporters that will write their output to a file rather than stdout",
              "additionalProperties": {
                "type": "string"
              }
            },
            "fold_stack_frames": {
              "$ref": "#/definitions/foldStackFrameOptions"
            },
            "custom_html_template_path": {
              "description": "This field specifies the path of the HTML template to be used for tests run in an HTML environment.",
              "type": "string"
            },
            "presets": {
              "type": "object",
              "additionalProperties": {
                "$ref": "#/definitions/runnerConfiguration"
              }
            },
            "add_presets": {
              "type": "array",
              "description": "Commonly used in a preset, it can be used to enable present inheritance by adding the configuration from another preset.",
              "items": {
                "type": "string"
              }
            },
            "on_os": {
              "type": "object",
              "description": "Applies test or runner options when a specific operating system is used",
              "additionalProperties": {
                "$ref": "#/definitions/runnerConfiguration"
              }
            },
            "override_platforms": {
              "type": "object",
              "additionalProperties": {
                "type": "object",
                "properties": {
                  "settings": {
                    "$ref": "#/definitions/browserAndNodeSettings"
                  }
                }
              }
            },
            "define_platforms": {
              "type": "object",
              "additionalProperties": {
                "type": "object",
                "properties": {
                  "name": {
                    "type": "string"
                  },
                  "extends": {
                    "type": "string"
                  },
                  "settings": {
                    "$ref": "#/definitions/browserAndNodeSettings"
                  }
                }
              }
            }
          }
        }
      ]
    }
  },
  "description": "Configuration for Dart tests",
  "title": "dart_test.yaml"
}

{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "id": "https://json.schemastore.org/vsls.json",
  "properties": {
    "excludeFiles": {
      "description": "An array of globs which indicate the files that should be completely unavailable to guests when you share (e.g. secrets).",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "gitignore": {
      "description": "Indicates how .gitignore files should be treated with respects to excluding/hiding files from guests.",
      "type": "string",
      "default": "hide",
      "enum": ["none", "hide", "exclude"]
    },
    "hideFiles": {
      "description": "An array of globs which indicate the files that should be hidden from guest's file trees, but still accessible (e.g. when following the host).",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "title": "JSON schema for Visual Studio Live Share config files",
  "type": "object"
}

{
  "$id": "https://raw.githubusercontent.com/Cog-Creators/Red-DiscordBot/V3/develop/schema/red_cog.schema.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Red-DiscordBot Сog metadata file",
  "type": "object",
  "properties": {
    "author": {
      "type": "array",
      "description": "List of names of authors of the cog",
      "items": {
        "type": "string"
      }
    },
    "description": {
      "type": "string",
      "description": "A long description of the cog or repo. For cogs, this is displayed when a user executes [p]cog info."
    },
    "install_msg": {
      "type": "string",
      "description": "The message that gets displayed when a cog is installed or a repo is added"
    },
    "short": {
      "type": "string",
      "description": "A short description of the cog or repo. For cogs, this info is displayed when a user executes [p]cog list"
    },
    "end_user_data_statement": {
      "type": "string",
      "description": "A statement explaining what end user data the cog is storing. This is displayed when a user executes [p]cog info. If the statement has changed since last update, user will be informed during the update."
    },
    "min_bot_version": {
      "type": "string",
      "description": "Min version number of Red in the format MAJOR.MINOR.MICRO",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)((a|b|rc)(0|[1-9][0-9]*))?(\\.post(0|[1-9][0-9]*))?(\\.dev(0|[1-9][0-9]*))?$"
    },
    "max_bot_version": {
      "type": "string",
      "description": "Max version number of Red in the format MAJOR.MINOR.MICRO, if min_bot_version is newer than max_bot_version, max_bot_version will be ignored",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)((a|b|rc)(0|[1-9][0-9]*))?(\\.post(0|[1-9][0-9]*))?(\\.dev(0|[1-9][0-9]*))?$"
    },
    "min_python_version": {
      "type": "array",
      "description": "Min version number of Python in the format [MAJOR, MINOR, PATCH]",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "integer"
      }
    },
    "hidden": {
      "type": "boolean",
      "description": "Determines if a cog is visible in the cog list for a repo."
    },
    "disabled": {
      "type": "boolean",
      "description": "Determines if a cog is available for install."
    },
    "required_cogs": {
      "type": "object",
      "description": "A dict of required cogs that this cog depends on in the format {cog_name : repo_url}. Downloader will not deal with this functionality but it may be useful for other cogs.",
      "$ref": "#/definitions/required_cog"
    },
    "requirements": {
      "type": "array",
      "description": "List of required libraries that are passed to pip on cog install.",
      "items": {
        "type": "string"
      }
    },
    "tags": {
      "type": "array",
      "description": "A list of strings that are related to the functionality of the cog. Used to aid in searching.",
      "uniqueItems": true,
      "items": {
        "type": "string"
      }
    },
    "type": {
      "type": "string",
      "description": "Optional, defaults to COG. Must be either COG or SHARED_LIBRARY. If SHARED_LIBRARY then hidden will be True.",
      "enum": [
        "COG",
        "SHARED_LIBRARY"
      ]
    }
  },
  "definitions": {
    "required_cog": {
      "type": "object",
      "patternProperties": {
        ".+": {
          "type": "string",
          "format": "uri"
        }
      },
      "additionalProperties": false
    }
  }
}

{
  "$comment": "https://www.jetbrains.com/help/qodana/qodana-yaml.html",
  "$id": "https://json.schemastore.org/qodana-1.0.json",
  "$schema": "http://json-schema.org/draft-07/schema#",
  "additionalProperties": true,
  "definitions": {
    "profile": {
      "description": "A profile is some template set of checks to run with Qodana analysis",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "name": {
              "description": "The profile name (embedded or located in the project)",
              "type": "string"
            }
          },
          "required": ["name"],
          "additionalProperties": false
        },
        {
          "properties": {
